CREATE TEMP TABLE _executive_person_ids ON COMMIT DROP AS
SELECT person_key.local_id, COALESCE(existing.id, incoming.id, person_key.target_id) AS target_id
FROM _executive_person_keys person_key
LEFT JOIN public.people existing ON existing.external_id = person_key.external_id
LEFT JOIN _executive_people incoming ON incoming.external_id = person_key.external_id;

CREATE TEMP TABLE _executive_election_ids ON COMMIT DROP AS
SELECT incoming.id AS local_id, COALESCE(existing.id, incoming.id) AS target_id
FROM _executive_elections incoming
LEFT JOIN public.elections existing ON existing.external_id = incoming.external_id;

CREATE TEMP TABLE _executive_race_ids ON COMMIT DROP AS
SELECT incoming.id AS local_id, COALESCE(existing.id, incoming.id) AS target_id
FROM _executive_races incoming
LEFT JOIN public.races existing ON existing.external_id = incoming.external_id;

CREATE TEMP TABLE _executive_candidate_ids ON COMMIT DROP AS
SELECT incoming.id AS local_id, COALESCE(existing.id, incoming.id) AS target_id
FROM _executive_candidates incoming
LEFT JOIN public.candidates existing ON existing.external_id = incoming.external_id;

UPDATE _executive_candidates incoming
SET person_id = ids.target_id
FROM _executive_person_ids ids
WHERE incoming.person_id = ids.local_id;

UPDATE _executive_candidates incoming
SET race_id = ids.target_id
FROM _executive_race_ids ids
WHERE incoming.race_id = ids.local_id;

UPDATE _executive_races incoming
SET election_id = ids.target_id
FROM _executive_election_ids ids
WHERE incoming.election_id = ids.local_id;

UPDATE _executive_people incoming SET id = ids.target_id FROM _executive_person_ids ids WHERE incoming.id = ids.local_id;
UPDATE _executive_elections incoming SET id = ids.target_id FROM _executive_election_ids ids WHERE incoming.id = ids.local_id;
UPDATE _executive_races incoming SET id = ids.target_id FROM _executive_race_ids ids WHERE incoming.id = ids.local_id;
UPDATE _executive_candidates incoming SET id = ids.target_id FROM _executive_candidate_ids ids WHERE incoming.id = ids.local_id;

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM _executive_people) <> 85
       OR (SELECT COUNT(*) FROM _executive_elections) <> 15
       OR (SELECT COUNT(*) FROM _executive_races) <> 126
       OR (SELECT COUNT(*) FROM _executive_candidates) <> 131 THEN
        RAISE EXCEPTION 'Elected executive production payload count drift';
    END IF;

    IF EXISTS (SELECT 1 FROM public.people existing JOIN _executive_people incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM public.elections existing JOIN _executive_elections incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM public.races existing JOIN _executive_races incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM public.candidates existing JOIN _executive_candidates incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id) THEN
        RAISE EXCEPTION 'Elected executive production identifier conflict';
    END IF;
END
$$;

INSERT INTO public.people (id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience)
SELECT id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience FROM _executive_people
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    alias = EXCLUDED.alias,
    party = EXCLUDED.party,
    position = EXCLUDED.position,
    election_year = EXCLUDED.election_year,
    district = EXCLUDED.district,
    source_url = EXCLUDED.source_url,
    is_public = EXCLUDED.is_public,
    updated_at = EXCLUDED.updated_at,
    external_id = EXCLUDED.external_id,
    gender = EXCLUDED.gender,
    education = EXCLUDED.education,
    experience = EXCLUDED.experience;

