SELECT id, person_id, race_id, party, candidate_no, registration_status, source_name, source_url, is_public, created_at, updated_at, external_id, vote_count, vote_rate, is_elected, is_incumbent, candidacy_status, election_result, status_updated_at FROM _executive_candidates
