    external_id = EXCLUDED.external_id,
    vote_count = EXCLUDED.vote_count,
    vote_rate = EXCLUDED.vote_rate,
    is_elected = EXCLUDED.is_elected,
    is_incumbent = EXCLUDED.is_incumbent,
    candidacy_status = EXCLUDED.candidacy_status,
    election_result = EXCLUDED.election_result,
    status_updated_at = EXCLUDED.status_updated_at;

SELECT public.refresh_public_people_list_cached();
SELECT published.promote(NULL);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM published.people item JOIN _executive_people release ON release.id = item.person_id) <> 85
       OR (SELECT COUNT(*) FROM published.elections item JOIN _executive_elections release ON release.id = item.election_id) <> 15
       OR (SELECT COUNT(*) FROM published.races item JOIN _executive_races release ON release.id = item.race_id) <> 126
       OR (SELECT COUNT(*) FROM published.candidates item JOIN _executive_candidates release ON release.id = item.candidate_id) <> 131 THEN
        RAISE EXCEPTION 'Elected executive production publication verification failed';
    END IF;
END
$$;

COMMIT;
